def compute_fibonacci(n):
    """Computes Fibonacci numbers up to F_n."""
    F = [0] * (n + 1)
    if n >= 0:
        F[0] = 0
    if n >= 1:
        F[1] = 1
    for i in range(2, n + 1):
        F[i] = F[i-1] + F[i-2]
    return F

