# Function to count distinct positive differences
def count_differences(S):
    """Counts the number of distinct positive differences x - y for x, y in S."""
    differences = set()
    for i in range(len(S)):
        for j in range(len(S)):
            if i != j:
                diff = S[i] - S[j]
                if diff > 0:
                    differences.add(diff)
    return len(differences)

