def calculate_coverage(S, target_F):
    """Calculates the ratio of covered Fibonacci numbers in S - S."""
    differences = set()
    S_list = sorted(list(S))
    n = len(S_list)

    # Generate all positive differences x - y where x > y
    for i in range(n):
        for j in range(i + 1, n):
            diff = S_list[j] - S_list[i]
            differences.add(diff)

    covered_count = 0
    for f_k in target_F:
        if f_k in differences:
            covered_count += 1

    ratio = covered_count / len(target_F)
    return covered_count, ratio

